from pathlib import Path
root=Path('/tmp/messenger-build/messenger_live/app/src/main/java/com/example/messengerui')
vm=root/'AppViewModel.kt'
s=vm.read_text()
s=s.replace('attachment.mimeType, attachment.displayName','attachment.mimeType ?: "image/jpeg", attachment.displayName',1)
vm.write_text(s)
app=root/'MessengerApp.kt'
s=app.read_text()
s=s.replace('if(vm.serverMode) vm.loadBusinessProfile{r->','if(vm.serverMode) vm.loadBusinessProfile(onReady={r->',1)
s=s.replace('            val arr=r.optJSONArray("catalogue");if(arr!=null){catalogue=readBusinessCatalogueServer(arr);saveCatalogue()}\n        }\n    }','            val arr=r.optJSONArray("catalogue");if(arr!=null){catalogue=readBusinessCatalogueServer(arr);saveCatalogue()}\n        })\n    }',1)
start=s.index('@Composable\nprivate fun PublicBusinessScreen')
end=s.index('\n@Composable\nprivate fun PrivacyScreen',start)
fn=bytes.fromhex('').decode('utf-8')
s=s[:start]+fn+s[end:]
app.write_text(s)
